const meridiemMatch = (input, isLowerCase) => {
  let isAfternoon
  const { meridiem } = locale || {}
  if (!meridiem) {
    isAfternoon = input === (isLowerCase ? 'pm' : 'PM')
  } else {
    for (let i = 1; i <= 24; i += 1) {
      if (input.indexOf(meridiem(i, 0, isLowerCase)) > -1) {
        isAfternoon = i > 12
        break
      }
    }
  }
  return isAfternoon
}

const getMeridiemRegex = (isLowerCase) => {
  const { meridiem } = locale || {}
  if (!meridiem) {
    return isLowerCase ? matchLowerCaseAMPM : matchUpperCaseAMPM
  }
  const values = []
  for (let i = 1; i <= 24; i += 1) {
    const value = meridiem(i, 0, isLowerCase)
    if (value && values.indexOf(value) < 0) values.push(value)
  }
  return new RegExp(values.join('|'))
